const parseLI = node({ type: 'n8n-nodes-base.code', version: 2, config: { name: "Parse LI + Gate", position: [1600, 160], parameters: {"mode": "runOnceForAllItems", "jsCode": "const STOPWORDS = new Set(['the', 'and', 'co', 'ltd', 'company', 'store', 'shop', 'hotel', 'resort', 'bangkok', 'yangon', 'thailand', 'myanmar', 'facebook', 'page', 'official']);
