function digResults(text) {
  let obj = null;
  try { obj = typeof text === 'string' ? JSON.parse(text) : text; } catch (e) { return null; }
  if (!obj || typeof obj !== 'object') return null;
  if (obj.structuredContent && Array.isArray(obj.structuredContent.results)) return obj.structuredContent.results;
  if (Array.isArray(obj.results)) return obj.results;
  let cur = obj;
  for (let depth = 0; depth < 4; depth++) {
    if (!cur || typeof cur !== 'object') break;
    if (Array.isArray(cur.results)) return cur.results;
    if (Array.isArray(cur.content)) { const c = cur.content.find(x => x && typeof x.text === 'string'); if (!c) break; try { cur = JSON.parse(c.text); } catch (e) { break; } continue; }
