}function dmEmployer(headlineRaw, titlePhrases) {
  const rawSegs = String(headlineRaw || '').split(/\s+at\s+|\s*@\s*|\s+of\s+|\s+[-–—]\s+|\s*[|•·\/,]\s*/i).map(x => normPhrase(x)).filter(Boolean);
